INSERT INTO public.categories (id, name, slug, headline, description, image_url, display_order) VALUES
  ('smartphones', 'Téléphones', 'smartphones', 'iPhone, Samsung, Tecno, Infinix, Xiaomi : neufs et garantis.', 'Smartphones neufs scellés de toutes gammes, du premier prix au haut de gamme.', '/images/cat-smartphones.svg', 1),
  ('protection', 'Pochettes & Verres', 'protection', 'Coques, pochettes et verres trempés pour protéger votre téléphone.', 'Coques antichoc, MagSafe, pochettes portefeuille et verres trempés 9D posés en boutique.', '/images/cat-protection.svg', 2),
  ('montres-connectees', 'Montres connectées', 'montres-connectees', 'Santé, sport, notifications : votre téléphone au poignet.', 'Apple Watch, Galaxy Watch, smartwatches et bracelets connectés.', '/images/cat-montres.svg', 3),
  ('chargeurs-gadgets', 'Chargeurs & Gadgets', 'chargeurs-gadgets', 'Chargeurs auto, power banks, écouteurs et accessoires du quotidien.', 'Chargeurs rapides, chargeurs voiture, power banks, écouteurs, câbles et enceintes.', '/images/cat-chargeurs.svg', 4)
INSERT INTO public.products (id, name, slug, category_id, sub_category, short_description, description, price, old_price, stock, brand, rating, review_count, badge, image_url, attributes, specs, features, is_featured, is_new, is_best_seller, is_promotion, is_active, display_order) VALUES
  ('prod-iphone-15-pro-max', 'iPhone 15 Pro Max 256 Go – Titane naturel', 'iphone-15-pro-max-256go-titane-naturel', 'smartphones', 'iPhone', 'Châssis en titane, puce A17 Pro et zoom optique 5x.', 'Le plus abouti des iPhone : design en titane léger, puce A17 Pro, triple caméra 48 Mpx avec téléobjectif 5x et port USB‑C. Livré neuf scellé avec facture et garantie boutique.', 790000, 850000, 4, 'Apple', 4.9, 38, 'Best Seller', '/images/prod-iphone-15-pro-max.svg', '{"Stockage":"256 Go","RAM":"8 Go","Réseau":"5G"}'::jsonb, '{"Marque":"Apple","Écran":"6,7\" OLED 120 Hz","Stockage":"256 Go","Caméra":"48 + 12 + 12 Mpx","Batterie":"Jusqu''à 29 h vidéo","État":"Neuf scellé"}'::jsonb, ARRAY['Écran Super Retina XDR 6,7" ProMotion 120 Hz', 'Puce A17 Pro', 'Triple caméra 48 Mpx, zoom optique 5x', 'Port USB‑C, Face ID', 'Neuf scellé + facture SBS']::text[], true, false, true, true, true, 1),
  ('prod-galaxy-s24-ultra', 'Samsung Galaxy S24 Ultra 256 Go – Titanium Black', 'samsung-galaxy-s24-ultra-256go', 'smartphones', 'Samsung Galaxy S', 'S Pen intégré, zoom 100x et Galaxy AI.', 'Le smartphone Android le plus complet : caméra 200 Mpx, zoom jusqu''à 100x, S Pen intégré et fonctions Galaxy AI (traduction d''appels, retouche photo). Version double SIM.', 720000, 780000, 3, 'Samsung', 4.9, 21, '-8%', '/images/prod-galaxy-s24-ultra.svg', '{"Stockage":"256 Go","RAM":"12 Go","Réseau":"5G"}'::jsonb, '{"Marque":"Samsung","Écran":"6,8\" AMOLED 120 Hz","Stockage":"256 Go","RAM":"12 Go","Batterie":"5000 mAh","État":"Neuf scellé"}'::jsonb, ARRAY['Écran Dynamic AMOLED 2X 6,8" 120 Hz', 'Caméra principale 200 Mpx', 'S Pen intégré', 'Batterie 5000 mAh, charge 45 W', 'Double SIM']::text[], true, false, true, true, true, 2),
  ('prod-galaxy-a55', 'Samsung Galaxy A55 5G 128 Go', 'samsung-galaxy-a55-5g-128go', 'smartphones', 'Samsung Galaxy A', 'Le milieu de gamme fiable : 5G, AMOLED et 4 ans de mises à jour.', 'Cadre en aluminium, écran Super AMOLED 120 Hz, triple caméra 50 Mpx stabilisée et batterie 5000 mAh. Le meilleur rapport qualité‑prix Samsung.', 235000, 255000, 9, 'Samsung', 4.8, 44, NULL, '/images/prod-galaxy-a55.svg', '{"Stockage":"128 Go","RAM":"8 Go","Réseau":"5G"}'::jsonb, '{"Marque":"Samsung","Écran":"6,6\" AMOLED","Stockage":"128 Go","RAM":"8 Go","Batterie":"5000 mAh","État":"Neuf scellé"}'::jsonb, ARRAY['Écran Super AMOLED 6,6" 120 Hz', 'Triple caméra 50 Mpx OIS', 'Batterie 5000 mAh', 'Résistant à l’eau IP67']::text[], true, false, true, false, true, 3),
  ('prod-tecno-camon-30', 'Tecno Camon 30 Pro 5G 256 Go', 'tecno-camon-30-pro-5g-256go', 'smartphones', 'Tecno Camon', 'Photo de nuit 50 Mpx et charge rapide 70 W.', 'Le photophone de Tecno : capteur 50 Mpx stabilisé, selfie 50 Mpx, écran AMOLED 144 Hz et charge 70 W. Idéal pour les créateurs de contenu.', 175000, 190000, 12, 'Tecno', 4.7, 27, 'Nouveau', '/images/prod-tecno-camon-30.svg', '{"Stockage":"256 Go","RAM":"12 Go","Réseau":"5G"}'::jsonb, '{"Marque":"Tecno","Écran":"6,78\" AMOLED 144 Hz","Stockage":"256 Go","RAM":"12 Go","Batterie":"5000 mAh","État":"Neuf scellé"}'::jsonb, ARRAY['Écran AMOLED 6,78" 144 Hz', 'Caméra 50 Mpx OIS + selfie 50 Mpx', 'Charge rapide 70 W', '12 Go RAM (+ extension)']::text[], false, true, false, false, true, 4),
  ('prod-infinix-note-40', 'Infinix Note 40 Pro 256 Go', 'infinix-note-40-pro-256go', 'smartphones', 'Infinix Note', 'Charge sans fil magnétique et écran courbé AMOLED.', 'Écran AMOLED incurvé 120 Hz, charge filaire 70 W et charge sans fil magnétique 20 W. Un design premium à petit prix.', 145000, 160000, 15, 'Infinix', 4.6, 33, NULL, '/images/prod-infinix-note-40.svg', '{"Stockage":"256 Go","RAM":"8 Go","Réseau":"4G"}'::jsonb, '{"Marque":"Infinix","Écran":"6,78\" AMOLED","Stockage":"256 Go","RAM":"8 Go","Batterie":"5000 mAh","État":"Neuf scellé"}'::jsonb, ARRAY['Écran AMOLED incurvé 6,78" 120 Hz', 'Charge 70 W + sans fil MagCharge 20 W', 'Caméra 108 Mpx', 'Haut-parleurs stéréo JBL']::text[], true, false, true, true, true, 5),
  ('prod-redmi-note-13', 'Xiaomi Redmi Note 13 Pro 256 Go', 'xiaomi-redmi-note-13-pro-256go', 'smartphones', 'Xiaomi Redmi', 'Caméra 200 Mpx et écran 1,5K à prix serré.', 'Caméra principale 200 Mpx, écran AMOLED 1,5K 120 Hz et charge turbo 67 W : la fiche technique d''un haut de gamme au prix d''un milieu de gamme.', 165000, NULL, 7, 'Xiaomi', 4.7, 19, NULL, '/images/prod-redmi-note-13.svg', '{"Stockage":"256 Go","RAM":"8 Go","Réseau":"4G"}'::jsonb, '{"Marque":"Xiaomi","Écran":"6,67\" AMOLED 1,5K","Stockage":"256 Go","RAM":"8 Go","Batterie":"5000 mAh","État":"Neuf scellé"}'::jsonb, ARRAY['Caméra 200 Mpx OIS', 'Écran AMOLED 1,5K 120 Hz', 'Charge turbo 67 W', 'Résistant aux éclaboussures IP54']::text[], false, true, false, false, true, 6),
  ('prod-coque-magsafe', 'Coque transparente MagSafe – iPhone 13 à 16', 'coque-transparente-magsafe-iphone', 'protection', 'Coques', 'Anneau magnétique MagSafe et anti‑jaunissement.', 'Coque rigide transparente qui laisse voir la couleur de votre iPhone. Aimants MagSafe intégrés, bords surélevés pour l’écran et la caméra.', 8000, 10000, 60, 'SBS Accessoires', 4.8, 52, '-20%', '/images/prod-coque-magsafe.svg', '{"Type":"Coque","Compatibilité":"iPhone"}'::jsonb, '{"Matière":"Polycarbonate + TPU","Compatibilité":"iPhone 13 à 16 (toutes tailles)","Couleur":"Transparent"}'::jsonb, ARRAY['Compatible charge MagSafe', 'Traitement anti‑jaunissement', 'Bords surélevés écran & caméra', 'Disponible du 13 au 16 Pro Max']::text[], true, false, true, true, true, 7),
  ('prod-verre-trempe-9d', 'Verre trempé Full Glue 9D (pose offerte en boutique)', 'verre-trempe-full-glue-9d', 'protection', 'Verres trempés', 'Protection bord à bord, dureté 9H.', 'Verre trempé intégral 9D qui couvre tout l’écran, sans bulles. Disponible pour iPhone, Samsung, Tecno, Infinix, Xiaomi, Itel… Pose gratuite en boutique.', 3000, NULL, 200, 'SBS Accessoires', 4.7, 118, NULL, '/images/prod-verre-trempe-9d.svg', '{"Type":"Verre trempé","Compatibilité":"Tous modèles"}'::jsonb, '{"Dureté":"9H","Épaisseur":"0,33 mm","Compatibilité":"Tous modèles (préciser à la commande)"}'::jsonb, ARRAY['Dureté 9H anti‑rayures', 'Colle intégrale : aucune bulle', 'Traitement oléophobe anti‑traces', 'Pose offerte en boutique']::text[], true, false, true, false, true, 8),
  ('prod-verre-anti-espion', 'Verre trempé anti‑espion (Privacy)', 'verre-trempe-anti-espion-privacy', 'protection', 'Verres trempés', 'Écran visible uniquement de face : confidentialité totale.', 'Filtre de confidentialité intégré : vos voisins voient un écran noir dès 30° d’angle. Idéal dans les transports et au bureau.', 5000, NULL, 80, 'SBS Accessoires', 4.6, 41, NULL, '/images/prod-verre-anti-espion.svg', '{"Type":"Verre trempé","Compatibilité":"Tous modèles"}'::jsonb, '{"Dureté":"9H","Angle de confidentialité":"30°","Compatibilité":"iPhone, Samsung, Tecno, Infinix"}'::jsonb, ARRAY['Filtre anti‑regard à 30°', 'Dureté 9H', 'Full Glue sans bulles', 'Pose offerte en boutique']::text[], false, true, false, false, true, 9),
  ('prod-pochette-cuir', 'Pochette portefeuille en cuir – Samsung Galaxy A & S', 'pochette-portefeuille-cuir-samsung', 'protection', 'Pochettes', '3 emplacements cartes, fermeture magnétique.', 'Étui folio en simili‑cuir avec rabat aimanté, 3 porte‑cartes et support vidéo. Protège l’écran et le dos de votre téléphone.', 7500, NULL, 35, 'SBS Accessoires', 4.6, 24, NULL, '/images/prod-pochette-cuir.svg', '{"Type":"Pochette","Compatibilité":"Samsung"}'::jsonb, '{"Matière":"Simili‑cuir premium","Compatibilité":"Galaxy A15 à A55, S23, S24","Couleurs":"Marron, Noir"}'::jsonb, ARRAY['Rabat magnétique', '3 porte‑cartes + poche billets', 'Fonction support vidéo', 'Coutures renforcées']::text[], false, false, false, false, true, 10),
  ('prod-coque-antichoc', 'Coque antichoc renforcée – Tecno / Infinix', 'coque-antichoc-renforcee-tecno-infinix', 'protection', 'Coques', 'Coins renforcés, résiste aux chutes de 2 m.', 'Double couche TPU + polycarbonate, coins à coussin d’air et dos antidérapant. Pour Tecno Spark/Camon et Infinix Hot/Note.', 5000, 6500, 70, 'SBS Accessoires', 4.5, 37, '-23%', '/images/prod-coque-antichoc.svg', '{"Type":"Coque","Compatibilité":"Tecno / Infinix"}'::jsonb, '{"Matière":"TPU + Polycarbonate","Compatibilité":"Tecno Spark, Camon / Infinix Hot, Note","Couleurs":"Noir, Orange"}'::jsonb, ARRAY['Protection chute 2 m', 'Coins à coussin d’air', 'Dos antidérapant', 'Noir ou orange']::text[], false, false, false, true, true, 11),
  ('prod-apple-watch-s9', 'Apple Watch Series 9 GPS 45 mm', 'apple-watch-series-9-45mm', 'montres-connectees', 'Apple Watch', 'Écran 2000 nits, ECG, suivi du sommeil.', 'L’Apple Watch la plus lumineuse : puce S9, double‑tap, ECG, oxymètre et détection des chutes. Bracelet sport inclus.', 295000, 320000, 4, 'Apple', 4.9, 16, NULL, '/images/prod-apple-watch-s9.svg', '{"Compatibilité":"iPhone"}'::jsonb, '{"Marque":"Apple","Boîtier":"45 mm aluminium","Compatibilité":"iPhone uniquement","Étanchéité":"50 m","État":"Neuf scellé"}'::jsonb, ARRAY['Écran Retina toujours activé 2000 nits', 'ECG, SpO2, suivi du sommeil', 'Geste double‑tap', 'Autonomie 18 h']::text[], true, false, true, false, true, 12),
  ('prod-galaxy-watch-6', 'Samsung Galaxy Watch6 44 mm', 'samsung-galaxy-watch6-44mm', 'montres-connectees', 'Galaxy Watch', 'Composition corporelle, ECG et Wear OS.', 'Montre ronde élégante avec écran Super AMOLED saphir, analyse de la composition corporelle, ECG et coaching sommeil.', 165000, 185000, 6, 'Samsung', 4.7, 14, '-11%', '/images/prod-galaxy-watch-6.svg', '{"Compatibilité":"Android"}'::jsonb, '{"Marque":"Samsung","Boîtier":"44 mm aluminium","Compatibilité":"Android","Étanchéité":"5 ATM","État":"Neuf scellé"}'::jsonb, ARRAY['Écran Super AMOLED 1,5" verre saphir', 'Analyse composition corporelle', 'ECG & tension', 'Wear OS + Google Play']::text[], false, false, false, true, true, 13),
  ('prod-smartwatch-ultra', 'Smartwatch Ultra 8 – AMOLED, appels Bluetooth', 'smartwatch-ultra-8-amoled-appels', 'montres-connectees', 'Smartwatch', 'Le look « Ultra » à petit prix, appels depuis le poignet.', 'Grand écran AMOLED 2,0", appels Bluetooth (micro + haut‑parleur), notifications WhatsApp, 100+ modes sport et 7 jours d’autonomie.', 25000, 35000, 40, 'Générique', 4.4, 63, '-29%', '/images/prod-smartwatch-ultra.svg', '{"Compatibilité":"iPhone & Android"}'::jsonb, '{"Écran":"2,0\" AMOLED","Compatibilité":"iPhone & Android","Autonomie":"7 jours","Étanchéité":"IP67"}'::jsonb, ARRAY['Écran AMOLED 2,0"', 'Appels Bluetooth', 'Notifications WhatsApp & SMS', 'Autonomie 7 jours']::text[], true, false, true, true, true, 14),
  ('prod-smart-band-8', 'Xiaomi Smart Band 8', 'xiaomi-smart-band-8', 'montres-connectees', 'Bracelets', 'Bracelet léger, 16 jours d’autonomie.', 'Le bracelet connecté le plus vendu : AMOLED 1,62", 150 modes sport, suivi du cœur et du sommeil, 16 jours d’autonomie.', 22000, NULL, 25, 'Xiaomi', 4.6, 29, NULL, '/images/prod-smart-band-8.svg', '{"Compatibilité":"iPhone & Android"}'::jsonb, '{"Marque":"Xiaomi","Écran":"1,62\" AMOLED","Compatibilité":"iPhone & Android","Étanchéité":"5 ATM"}'::jsonb, ARRAY['AMOLED 1,62" 60 Hz', '150+ modes sport', 'SpO2 & fréquence cardiaque', 'Autonomie 16 jours']::text[], false, true, false, false, true, 15),
  ('prod-chargeur-auto-38w', 'Chargeur voiture 38 W USB‑C PD + USB‑A', 'chargeur-voiture-38w-usbc-pd', 'chargeurs-gadgets', 'Chargeurs auto', 'Deux téléphones en charge rapide sur l’allume‑cigare.', 'Chargeur allume‑cigare 12/24 V avec port USB‑C Power Delivery 20 W et port USB‑A Quick Charge 18 W. Câble USB‑C offert.', 7500, 9000, 50, 'SBS Accessoires', 4.7, 58, 'Best Seller', '/images/prod-chargeur-auto-38w.svg', '{"Type":"Chargeur auto","Connectique":"USB-C"}'::jsonb, '{"Puissance":"38 W","Ports":"USB‑C + USB‑A","Tension":"12–24 V"}'::jsonb, ARRAY['USB‑C PD 20 W + USB‑A QC 18 W', 'Compatible 12 V / 24 V', 'Protection surchauffe & court‑circuit', 'Câble USB‑C offert']::text[], true, false, true, true, true, 16),
  ('prod-chargeur-samsung-25w', 'Chargeur rapide Samsung 25 W + câble USB‑C', 'chargeur-rapide-samsung-25w-cable', 'chargeurs-gadgets', 'Chargeurs secteur', 'Super Fast Charging d’origine.', 'Adaptateur secteur Samsung 25 W Super Fast Charging avec câble USB‑C vers USB‑C 1 m. Compatible Galaxy A, S et tout appareil USB‑C.', 9000, NULL, 45, 'Samsung', 4.8, 47, NULL, '/images/prod-chargeur-samsung-25w.svg', '{"Type":"Chargeur secteur","Connectique":"USB-C"}'::jsonb, '{"Marque":"Samsung","Puissance":"25 W","Câble":"USB‑C / USB‑C 1 m"}'::jsonb, ARRAY['Super Fast Charging 25 W', 'Câble USB‑C 1 m inclus', 'Prise européenne', 'Compatible tous USB‑C']::text[], false, false, false, false, true, 17),
  ('prod-powerbank-20000', 'Power Bank 20 000 mAh charge rapide 22,5 W', 'power-bank-20000mah-22w', 'chargeurs-gadgets', 'Power banks', '4 à 5 recharges complètes, idéal contre les coupures.', 'Batterie externe 20 000 mAh avec charge rapide 22,5 W, 3 sorties (2 USB‑A + USB‑C) et indicateur LED. Votre allié pendant les délestages.', 15000, 18000, 30, 'SBS Accessoires', 4.7, 71, NULL, '/images/prod-powerbank-20000.svg', '{"Type":"Power bank","Connectique":"USB-C"}'::jsonb, '{"Capacité":"20 000 mAh","Puissance":"22,5 W","Ports":"2× USB‑A, 1× USB‑C"}'::jsonb, ARRAY['Capacité 20 000 mAh', 'Charge rapide 22,5 W', '3 sorties simultanées', 'Indicateur LED de niveau']::text[], true, false, true, true, true, 18),
  ('prod-ecouteurs-tws', 'Écouteurs Bluetooth TWS Pro – réduction de bruit', 'ecouteurs-bluetooth-tws-pro', 'chargeurs-gadgets', 'Écouteurs', 'Sans fil, réduction de bruit, 30 h avec le boîtier.', 'Écouteurs intra‑auriculaires Bluetooth 5.3 avec réduction de bruit, commandes tactiles et boîtier de charge USB‑C.', 12000, NULL, 40, 'SBS Accessoires', 4.5, 39, NULL, '/images/prod-ecouteurs-tws.svg', '{"Type":"Écouteurs","Connectique":"Bluetooth"}'::jsonb, '{"Bluetooth":"5.3","Autonomie":"6 h (+24 h boîtier)","Charge":"USB‑C"}'::jsonb, ARRAY['Bluetooth 5.3', 'Réduction de bruit', '30 h avec le boîtier', 'Commandes tactiles']::text[], false, true, false, false, true, 19),
  ('prod-airpods-pro-2', 'Apple AirPods Pro (2ᵉ génération) USB‑C', 'apple-airpods-pro-2-usbc', 'chargeurs-gadgets', 'Écouteurs', 'Réduction de bruit active 2x plus efficace.', 'Puce H2, réduction active du bruit, mode Transparence adaptative et audio spatial. Boîtier MagSafe USB‑C avec haut‑parleur.', 135000, 150000, 5, 'Apple', 4.9, 22, NULL, '/images/prod-airpods-pro-2.svg', '{"Type":"Écouteurs","Connectique":"Bluetooth"}'::jsonb, '{"Marque":"Apple","Puce":"H2","Autonomie":"6 h (+30 h boîtier)","État":"Neuf scellé"}'::jsonb, ARRAY['Réduction active du bruit', 'Audio spatial personnalisé', 'Boîtier MagSafe USB‑C', 'Résistant à l’eau IP54']::text[], true, false, true, false, true, 20),
  ('prod-support-voiture-mag', 'Support téléphone voiture magnétique', 'support-telephone-voiture-magnetique', 'chargeurs-gadgets', 'Supports', 'Fixation grille d’aération, rotation 360°.', 'Support aimanté puissant pour grille d’aération : posez votre téléphone d’une main, rotation 360° pour le GPS. Plaques métalliques fournies.', 6000, NULL, 35, 'SBS Accessoires', 4.5, 18, NULL, '/images/prod-support-voiture-mag.svg', '{"Type":"Support voiture","Connectique":"MagSafe"}'::jsonb, '{"Fixation":"Grille d’aération","Compatibilité":"Tous smartphones","Rotation":"360°"}'::jsonb, ARRAY['Aimants N52 puissants', 'Rotation 360°', 'Pince grille d’aération', '2 plaques métalliques incluses']::text[], false, false, false, false, true, 21),
  ('prod-cable-usbc-lightning', 'Câble USB‑C vers Lightning tressé 1 m', 'cable-usbc-lightning-tresse-1m', 'chargeurs-gadgets', 'Câbles', 'Charge rapide iPhone, gaine nylon renforcée.', 'Câble tressé nylon pour charge rapide 20 W des iPhone 8 à 14. Embouts renforcés testés à 10 000 pliages.', 4000, NULL, 100, 'SBS Accessoires', 4.6, 55, NULL, '/images/prod-cable-usbc-lightning.svg', '{"Type":"Câble","Connectique":"Lightning"}'::jsonb, '{"Longueur":"1 m","Connecteurs":"USB‑C → Lightning","Compatibilité":"iPhone 8 à 14"}'::jsonb, ARRAY['Charge rapide 20 W', 'Gaine nylon tressée', 'Testé 10 000 pliages', 'Longueur 1 m']::text[], false, false, false, false, true, 22),
  ('prod-enceinte-flip', 'Enceinte Bluetooth portable étanche 20 W', 'enceinte-bluetooth-portable-etanche', 'chargeurs-gadgets', 'Enceintes', 'Son puissant, étanche IPX7, 12 h d’autonomie.', 'Enceinte nomade 20 W aux basses profondes, étanche IPX7, Bluetooth 5.3 et 12 h d’autonomie. Parfaite pour la plage et les sorties.', 18000, 22000, 20, 'SBS Accessoires', 4.6, 26, '-18%', '/images/prod-enceinte-flip.svg', '{"Type":"Enceinte","Connectique":"Bluetooth"}'::jsonb, '{"Puissance":"20 W","Étanchéité":"IPX7","Autonomie":"12 h","Bluetooth":"5.3"}'::jsonb, ARRAY['Puissance 20 W, basses renforcées', 'Étanche IPX7', 'Autonomie 12 h', 'Appairage stéréo de 2 enceintes']::text[], false, false, false, true, true, 23)
INSERT INTO public.reviews (product_name, author_name, location, rating, title, content, verified_purchase, is_approved) VALUES
  ('Samsung Galaxy A55 5G 128 Go', 'Client démo A.', 'Douala, Akwa', 5, 'Téléphone neuf scellé, comme promis', 'Commande passée sur WhatsApp le matin, livré à Akwa l’après‑midi. Le verre trempé a été posé gratuitement. Exemple d’avis à remplacer.', false, true),
  ('Power Bank 20 000 mAh charge rapide 22,5 W', 'Client démo B.', 'Douala, Bonamoussadi', 5, 'Power bank très utile', 'Elle recharge mon téléphone plus de 4 fois, parfait pendant les coupures. Exemple d’avis à remplacer.', false, true),
  ('Smartwatch Ultra 8 – AMOLED, appels Bluetooth', 'Client démo C.', 'Yaoundé', 4, 'Montre au top pour le prix', 'Bel écran, les notifications WhatsApp marchent bien. Expédiée à Yaoundé en 48 h. Exemple d’avis à remplacer.', false, true);
INSERT INTO public.promotions (code, discount_percent, min_spend) VALUES ('SBS10', 10, 0) ON CONFLICT (code) DO NOTHING;
